import{_ as l,a0 as o,w as p,s as d,ao as r,I as n,x as s,a1 as i,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"如何使用 Linux 防火牆隔離本地欺騙地址 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 Linux 防火牆隔離本地欺騙地址 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 Linux 防火牆隔離本地欺騙地址 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 Linux 防火牆隔離本地欺騙地址 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20180227 How to block local spoofed addresses using the Linux firewall","title":"如何使用 Linux 防火牆隔離本地欺騙地址","tag":"201805","desc":""},"relativePath":"201805/20180227 How to block local spoofed addresses using the Linux firewall.md","filePath":"[post].md"}'),c={name:"201805/20180227 How to block local spoofed addresses using the Linux firewall.md"};function u(f,e,b,g,h,m){const a=o("Link");return p(),d("div",null,[e[13]||(e[13]=r(`<h1 id="如何使用-linux-防火牆隔離本地欺騙地址" tabindex="-1">如何使用 Linux 防火牆隔離本地欺騙地址 <a class="header-anchor" href="#如何使用-linux-防火牆隔離本地欺騙地址" aria-label="Permalink to “如何使用 Linux 防火牆隔離本地欺騙地址”">​</a></h1><blockquote><p>如何使用 iptables 防火牆保護你的網絡免遭黑客攻擊。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/EDU_UnspokenBlockers_1110_A.png?itok=x8A9mqVA" alt=""></p><p>即便是被入侵檢測和隔離系統所保護的遠程網絡，黑客們也在尋找各種精巧的方法入侵。IDS/IPS 不能停止或者減少那些想要接管你的網絡控制權的黑客攻擊。不恰當的配置允許攻擊者繞過所有部署的安全措施。</p><p>在這篇文章中，我將會解釋安全工程師或者系統管理員該怎樣避免這些攻擊。</p><p>幾乎所有的 Linux 發行版都帶着一個內建的防火牆來保護運行在 Linux 主機上的進程和應用程序。大多數防火牆都按照 IDS/IPS 解決方案設計，這樣的設計的主要目的是檢測和避免惡意包獲取網絡的進入權。</p><p>Linux 防火牆通常有兩種接口：iptables 和 ipchains 程序（LCTT 譯註：在支持 systemd 的系統上，採用的是更新的接口 firewalld）。大多數人將這些接口稱作 iptables 防火牆或者 ipchains 防火牆。這兩個接口都被設計成包過濾器。iptables 是有狀態防火牆，其基於先前的包做出決定。ipchains 不會基於先前的包做出決定，它被設計為無狀態防火牆。</p><p>在這篇文章中，我們將會專注於內核 2.4 之後出現的 iptables 防火牆。</p><p>有了 iptables 防火牆，你可以創建策略或者有序的規則集，規則集可以告訴內核該如何對待特定的數據包。在內核中的是Netfilter 框架。Netfilter 既是框架也是 iptables 防火牆的項目名稱。作為一個框架，Netfilter 允許 iptables 勾連被設計來操作數據包的功能。概括地説，iptables 依靠 Netfilter 框架構築諸如過濾數據包數據的功能。</p><p>每個 iptables 規則都被應用到一個表中的鏈上。一個 iptables 鏈就是一個比較包中相似特徵的規則集合。而表（例如 <code>nat</code> 或者 <code>mangle</code>）則描述不同的功能目錄。例如， <code>mangle</code> 表用於修改包數據。因此，特定的修改包數據的規則被應用到這裏；而過濾規則被應用到 <code>filter</code> 表，因為 <code>filter</code> 表過濾包數據。</p><p>iptables 規則有一個匹配集，以及一個諸如 <code>Drop</code> 或者 <code>Deny</code> 的目標，這可以告訴 iptables 對一個包做什麼以符合規則。因此，沒有目標和匹配集，iptables 就不能有效地處理包。如果一個包匹配了一條規則，目標會指向一個將要採取的特定措施。另一方面，為了讓 iptables 處理，每個數據包必須匹配才能被處理。</p><p>現在我們已經知道 iptables 防火牆如何工作，讓我們着眼於如何使用 iptables 防火牆檢測並拒絕或丟棄欺騙地址吧。</p><h3 id="打開源地址驗證" tabindex="-1">打開源地址驗證 <a class="header-anchor" href="#打開源地址驗證" aria-label="Permalink to “打開源地址驗證”">​</a></h3><p>作為一個安全工程師，在處理遠程的欺騙地址的時候，我採取的第一步是在內核打開源地址驗證。</p><p>源地址驗證是一種內核層級的特性，這種特性丟棄那些偽裝成來自你的網絡的包。這種特性使用反向路徑過濾器方法來檢查收到的包的源地址是否可以通過包到達的接口可以到達。（LCTT 譯註：到達的包的源地址應該可以從它到達的網絡接口反向到達，只需反轉源地址和目的地址就可以達到這樣的效果）</p><p>利用下面簡單的腳本可以打開源地址驗證而不用手工操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/sh</span></span>
<span class="line"><span>#作者: Michael K Aboagye</span></span>
<span class="line"><span>#程序目標: 打開反向路徑過濾</span></span>
<span class="line"><span>#日期: 7/02/18</span></span>
<span class="line"><span>#在屏幕上顯示 “enabling source address verification”</span></span>
<span class="line"><span>echo -n &quot;Enabling source address verification…&quot;</span></span>
<span class="line"><span>#將值0覆蓋為1來打開源地址驗證</span></span>
<span class="line"><span>echo 1 &gt; /proc/sys/net/ipv4/conf/default/rp_filter</span></span>
<span class="line"><span>echo &quot;completed&quot;</span></span></code></pre></div><p>上面的腳本在執行的時候只顯示了 <code>Enabling source address verification</code> 這條信息而不會換行。默認的反向路徑過濾的值是 <code>0</code>，<code>0</code> 表示沒有源驗證。因此，第二行簡單地將默認值 <code>0</code> 覆蓋為 <code>1</code>。<code>1</code> 表示內核將會通過確認反向路徑來驗證源地址。</p><p>最後，你可以使用下面的命令通過選擇 <code>DROP</code> 或者 <code>REJECT</code> 目標之一來丟棄或者拒絕來自遠端主機的欺騙地址。但是，處於安全原因的考慮，我建議使用 <code>DROP</code> 目標。</p><p>像下面這樣，用你自己的 IP 地址代替 <code>IP-address</code> 佔位符。另外，你必須選擇使用 <code>REJECT</code> 或者 <code>DROP</code> 中的一個，這兩個目標不能同時使用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>iptables -A INPUT -i internal_interface -s IP_address -j REJECT / DROP  </span></span>
<span class="line"><span>iptables -A INPUT -i internal_interface -s 192.168.0.0/16  -j REJECT / DROP</span></span></code></pre></div><p>這篇文章只提供瞭如何使用 iptables 防火牆來避免遠端欺騙攻擊的基礎知識。</p><hr>`,23)),n("p",null,[e[1]||(e[1]=s("via: ",-1)),i(a,{href:"https://opensource.com/article/18/2/block-local-spoofed-addresses-using-linux-firewall"},{default:t(()=>[...e[0]||(e[0]=[s("https://opensource.com/article/18/2/block-local-spoofed-addresses-using-linux-firewall",-1)])]),_:1})]),n("p",null,[e[5]||(e[5]=s("作者：",-1)),i(a,{href:"https://opensource.com/users/revoks"},{default:t(()=>[...e[2]||(e[2]=[s("Michael Kwaku Aboagye",-1)])]),_:1}),e[6]||(e[6]=s(" 譯者：",-1)),i(a,{href:"https://github.com/leemeans"},{default:t(()=>[...e[3]||(e[3]=[s("leemeans",-1)])]),_:1}),e[7]||(e[7]=s(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:t(()=>[...e[4]||(e[4]=[s("wxy",-1)])]),_:1})]),n("p",null,[e[10]||(e[10]=s("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[8]||(e[8]=[s("LCTT",-1)])]),_:1}),e[11]||(e[11]=s(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:t(()=>[...e[9]||(e[9]=[s("Linux中國",-1)])]),_:1}),e[12]||(e[12]=s(" 榮譽推出",-1))])])}const C=l(c,[["render",u]]);export{T as __pageData,C as default};
